INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, "リリ", 24001, 1, 2, 125801, 40011, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 321, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, "クリア", 24001, 2, 2, 126001, 40011, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 1, 322, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, "プレシア", 24001, 3, 2, 126101, 40011, "んーと。\nこれ、あげる。\nはい", 1, 323, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, "リリ", 24001, 4, 2, 125801, 40011, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 1, 324, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, "クリア", 24001, 5, 2, 126001, 40011, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 1, 325, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, "プレシア", 24001, 6, 2, 126101, 40011, "お兄。\nきてくれて、うれしい", 1, 326, 0);
